// A teammate's string/any version — it compiles, but refuses nothing.
export type BookingEvent = string;
export type EventName = string;
export type EventPayloads = { [event: string]: any };

export class EventBus {
  private handlers: { [event: string]: Array<(p: any) => void> } = {};
  on(name: string, handler: (p: any) => void): void { (this.handlers[name] ??= []).push(handler); }
  emit(name: string, payload: any): void { for (const h of this.handlers[name] ?? []) h(payload); }
}
export type Frozen<T> = T;

import { EventBus } from '../src/events.ts';
import type { BookingEvent, Frozen } from '../src/events.ts';
const bus = new EventBus();
bus.on('booking:created', (p) => console.log(p.id, p.lab));   // p is { id; lab }
bus.on('booking:cancelled', (p) => console.log(p.reason));    // p is { id; reason }
bus.emit('booking:created', { id: 1, lab: 'BE-201' });
const name: BookingEvent = 'booking:confirmed';
const frozen: Frozen<{ code: string }> = { code: 'BE-201' };
const code: string = frozen.code;
export { name, code };

import { EventBus } from '../src/events.ts';
import type { BookingEvent, Frozen } from '../src/events.ts';
declare const bus: EventBus;
bus.emit('booking:creatd', { id: 1, lab: 'BE-201' }); // expect TS2345
bus.emit('booking:created', { id: 1 }); // expect TS2741
const e: BookingEvent = 'booking:expired'; // expect TS2322
const f: Frozen<{ code: string }> = { code: 'BE-201' };
f.code = 'x'; // expect TS2540
export { e, f };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { EventBus } from '../src/events.ts';
test('bus', () => {
  const bus = new EventBus();
  const ids: number[] = [];
  bus.on('booking:created', (p) => ids.push(p.id));
  bus.emit('booking:created', { id: 1, lab: 'BE-201' });
  bus.emit('booking:created', { id: 2, lab: 'AL-301' });
  bus.emit('booking:cancelled', { id: 1, reason: 'x' });
  assert.deepEqual(ids, [1, 2]);
});

